import { strict as assert } from 'node:assert';
import fs from 'node:fs';
import path from 'node:path';

const originalAssertMatch = assert.match.bind(assert);

const assertIncludes = (content: string, searchString: string, message: string) => {
  assert.ok(content.includes(searchString), message);
};

function readSourceSection(source: string, startNeedle: string, endNeedle: string): string {
  const start = source.indexOf(startNeedle);
  assert.notEqual(start, -1, `Missing source section start: ${startNeedle}`);
  const end = source.indexOf(endNeedle, start);
  assert.notEqual(end, -1, `Missing source section end: ${endNeedle}`);
  return source.slice(start, end);
}

type SafeLookaheadAssertion = {
  body: string;
  negative: boolean;
};

function readSafeLookaheadAssertion(source: string, startIndex: number): { assertion: SafeLookaheadAssertion; endIndex: number } | null {
  const operator = source.slice(startIndex, startIndex + 3);
  if (operator !== '(?=' && operator !== '(?!') {
    return null;
  }

  let depth = 1;
  let inCharacterClass = false;
  for (let index = startIndex + 3; index < source.length; index += 1) {
    const char = source[index];
    if (char === '\\') {
      index += 1;
      continue;
    }
    if (inCharacterClass) {
      if (char === ']') {
        inCharacterClass = false;
      }
      continue;
    }
    if (char === '[') {
      inCharacterClass = true;
      continue;
    }
    if (char === '(') {
      depth += 1;
      continue;
    }
    if (char === ')') {
      depth -= 1;
      if (depth === 0) {
        return {
          assertion: {
            body: source.slice(startIndex + 3, index),
            negative: operator === '(?!',
          },
          endIndex: index + 1,
        };
      }
    }
  }

  return null;
}

function splitSafeLookaheadAssertions(source: string): SafeLookaheadAssertion[] | null {
  if (!source.startsWith('(?=')) {
    return null;
  }

  const assertions: SafeLookaheadAssertion[] = [];
  let index = 0;
  while (index < source.length) {
    const parsed = readSafeLookaheadAssertion(source, index);
    if (parsed === null) {
      const remainder = source.slice(index);
      if (remainder === '' || remainder === '[\\s\\S]*' || remainder === '.*') {
        return assertions;
      }
      return null;
    }
    assertions.push(parsed.assertion);
    index = parsed.endIndex;
  }

  return assertions;
}

function assertSafeLookaheadMatch(actual: string, expected: RegExp, message?: string | Error): boolean {
  const assertions = splitSafeLookaheadAssertions(expected.source);
  if (assertions === null) {
    return false;
  }

  const flags = expected.flags.replaceAll('g', '').replaceAll('y', '');
  for (const assertion of assertions) {
    const matched = safeSequentialRegexMatch(actual, assertion.body, flags);
    if (assertion.negative) {
      assert.ok(matched === false, message);
      continue;
    }
    assert.ok(matched === true, message);
  }
  return true;
}

function safeSequentialRegexMatch(actual: string, source: string, flags: string): boolean {
  if (!source.includes('[\\s\\S]*')) {
    return new RegExp(source, flags).test(actual);
  }

  const segments = source.split(/\[\\s\\S\]\*\??/g);
  let cursor = 0;
  for (const segment of segments) {
    if (segment === '') {
      continue;
    }
    const segmentPattern = new RegExp(segment, flags);
    const match = segmentPattern.exec(actual.slice(cursor));
    if (match === null || match.index === undefined) {
      return false;
    }
    cursor += match.index + match[0].length;
  }
  return true;
}

function assertSafeSequentialMatch(actual: string, expected: RegExp, message?: string | Error): boolean {
  if (!expected.source.includes('[\\s\\S]*')) {
    return false;
  }
  const flags = expected.flags.replaceAll('g', '').replaceAll('y', '');
  assert.ok(safeSequentialRegexMatch(actual, expected.source, flags), message);
  return true;
}

assert.match = ((actual: string, expected: RegExp, message?: string | Error) => {
  if (typeof actual === 'string' && expected instanceof RegExp) {
    const handled = assertSafeLookaheadMatch(actual, expected, message);
    if (handled) {
      return;
    }
    const sequentialHandled = assertSafeSequentialMatch(actual, expected, message);
    if (sequentialHandled) {
      return;
    }
  }
  originalAssertMatch(actual, expected, message);
}) as typeof assert.match;

type GovernedFrontendSourceFilePathList = string[];

type GovernedFrontendArrayPipelineViolation = {
  filePath: string;
  lineNumber: number;
  line: string;
};

type GovernedFrontendArrayPipelineViolationList = GovernedFrontendArrayPipelineViolation[];

const governedFrontendArrayPipelinePattern = /\.(map|filter|find|findIndex|some|forEach|reduce)\(/;

const governedFrontendSourceRoots = [
  'src/app',
  'src/components',
  'src/lib',
];

function isGovernedFrontendSourceFile(filePath: string): boolean {
  if (filePath.endsWith('.ts')) {
    return true;
  }

  if (filePath.endsWith('.tsx')) {
    return true;
  }

  return false;
}

function collectGovernedFrontendSourceFilePaths(rootPath: string): GovernedFrontendSourceFilePathList {
  const filePaths: GovernedFrontendSourceFilePathList = [];
  const entries = fs.readdirSync(rootPath, { withFileTypes: true });

  for (const entry of entries) {
    const entryPath = path.join(rootPath, entry.name);

    if (entry.isDirectory()) {
      const childFilePaths = collectGovernedFrontendSourceFilePaths(entryPath);
      for (const childFilePath of childFilePaths) {
        filePaths.push(childFilePath);
      }
      continue;
    }

    if (entry.isFile() === false) {
      continue;
    }

    if (isGovernedFrontendSourceFile(entryPath) === false) {
      continue;
    }

    filePaths.push(entryPath);
  }

  return filePaths;
}

function collectGovernedFrontendArrayPipelineViolations(
  filePath: string,
): GovernedFrontendArrayPipelineViolationList {
  const violations: GovernedFrontendArrayPipelineViolationList = [];
  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n');

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    const hasViolation = governedFrontendArrayPipelinePattern.test(line);

    if (hasViolation === false) {
      continue;
    }

    violations.push({
      filePath,
      lineNumber: index + 1,
      line: line.trim(),
    });
  }

  return violations;
}

function collectGovernedFrontendArrayPipelineViolationReport(): string {
  const violations: GovernedFrontendArrayPipelineViolationList = [];

  for (const sourceRoot of governedFrontendSourceRoots) {
    const sourceFilePaths = collectGovernedFrontendSourceFilePaths(sourceRoot);

    for (const sourceFilePath of sourceFilePaths) {
      const sourceViolations = collectGovernedFrontendArrayPipelineViolations(sourceFilePath);

      for (const sourceViolation of sourceViolations) {
        violations.push(sourceViolation);
      }
    }
  }

  if (violations.length === 0) {
    return '';
  }

  const reportLines: string[] = [];
  for (const violation of violations) {
    reportLines.push(`${violation.filePath}:${violation.lineNumber}: ${violation.line}`);
  }

  return reportLines.join('\n');
}

const getSourceSection = (content: string, startMarker: string, endMarker: string, message: string) => {
  const startIndex = content.indexOf(startMarker);
  assert.notEqual(startIndex, -1, `${message}: missing start marker`);
  const endIndex = content.indexOf(endMarker, startIndex);
  assert.notEqual(endIndex, -1, `${message}: missing end marker`);

  return content.slice(startIndex, endIndex);
};

const getSourceSectionToEnd = (content: string, startMarker: string, message: string) => {
  const startIndex = content.indexOf(startMarker);
  assert.notEqual(startIndex, -1, `${message}: missing start marker`);

  return content.slice(startIndex);
};

