const workspaceGitConfirmationGatePanels = [
  { label: 'Desktop', source: desktopGitPanel },
  { label: 'Mobile', source: mobileGitPanel },
] as const;
const workspaceGitConfirmationGates = [
  {
    pending: 'pendingBranchCompareFileApplyConfirmation',
    snapshot: 'gitBranchCompareFileApplyConfirmationSnapshot',
    confirming: 'isConfirmingBranchCompareFileApply',
    handler: 'handleConfirmBranchCompareFileApply',
  },
  {
    pending: 'pendingCommitFileRestoreConfirmation',
    snapshot: 'gitCommitFileRestoreConfirmationSnapshot',
    confirming: 'isConfirmingCommitFileRestore',
    handler: 'handleConfirmCommitFileRestore',
  },
  {
    pending: 'pendingBranchMutationConfirmation',
    snapshot: 'gitBranchMutationConfirmationSnapshot',
    confirming: 'isConfirmingBranchMutation',
    handler: 'handleConfirmBranchMutation',
  },
  {
    pending: 'pendingBranchSwitchConfirmation',
    snapshot: 'gitBranchSwitchConfirmationSnapshot',
    confirming: 'isConfirmingBranchSwitch',
    handler: 'handleConfirmBranchSwitch',
  },
  {
    pending: 'pendingTagMutationConfirmation',
    snapshot: 'gitTagMutationConfirmationSnapshot',
    confirming: 'isConfirmingTagMutation',
    handler: 'handleConfirmTagMutation',
  },
  {
    pending: 'pendingRemoteBranchRefreshConfirmation',
    snapshot: 'gitRemoteBranchRefreshConfirmationSnapshot',
    confirming: 'isConfirmingRemoteBranchRefresh',
    handler: 'handleConfirmRemoteBranchRefresh',
  },
  {
    pending: 'pendingRemoteBranchCreateConfirmation',
    snapshot: 'gitRemoteBranchCreateConfirmationSnapshot',
    confirming: 'isConfirmingRemoteBranchCreate',
    handler: 'handleConfirmRemoteBranchCreate',
  },
  {
    pending: 'pendingStashMutationConfirmation',
    snapshot: 'gitStashMutationConfirmationSnapshot',
    confirming: 'isConfirmingStashMutation',
    handler: 'handleConfirmStashMutation',
  },
  {
    pending: 'pendingWorktreeCommitConfirmation',
    snapshot: 'gitWorktreeCommitConfirmationSnapshot',
    confirming: 'isConfirmingWorktreeCommit',
    handler: 'handleConfirmWorktreeCommit',
  },
  {
    pending: 'pendingWorktreeFileDiscardConfirmation',
    snapshot: 'gitWorktreeFileDiscardConfirmationSnapshot',
    confirming: 'isConfirmingWorktreeFileDiscard',
    handler: 'handleConfirmWorktreeFileDiscard',
  },
] as const;
for (const { label, source } of workspaceGitConfirmationGatePanels) {
  for (const { pending, snapshot, confirming, handler } of workspaceGitConfirmationGates) {
    assert.ok(
      source.includes(`${pending} === null`) && source.includes(`${snapshot}.canConfirm !== true`),
      `${label} Git confirmation ${pending} should use explicit null and canConfirm guards`,
    );
    assert.ok(
      source.includes(`open={${pending} !== null}`),
      `${label} Git confirmation ${pending} should use explicit non-null dialog open state`,
    );
    assert.ok(
      source.includes(`open === false && ${confirming} === false`),
      `${label} Git confirmation ${pending} should use explicit dialog close gate`,
    );
    assert.ok(
      source.includes(`disabled={${snapshot}.canCancel === false}`) &&
        source.includes(`disabled={${snapshot}.canConfirm === false}`),
      `${label} Git confirmation ${pending} should use explicit disabled gates`,
    );
    assert.ok(
      source.includes(`void ${handler}();`),
      `${label} Git confirmation ${pending} should call the existing async handler from the confirmation button`,
    );
  }
}
